// buildClusterMemberWhere recursively builds a WHERE clause string and arguments.
func buildClusterMemberWhere(c *Client, wheres []query.ClusterMemberWhereClause, argIdx *int) (string, []any) {
	var parts []string
	var args []any
	for _, w := range wheres {
		switch w.Field {
		case "__AND__":
			if subs, ok := w.Value.([]query.ClusterMemberWhereClause); ok {
				sub, subArgs := buildClusterMemberWhere(c, subs, argIdx)
				if sub != "" {
					parts = append(parts, "("+sub+")")
				}
				args = append(args, subArgs...)
			}
		case "__OR__":
			if subs, ok := w.Value.([]query.ClusterMemberWhereClause); ok {
				var orParts []string
				for _, sc := range subs {
					sub, subArgs := buildClusterMemberWhere(c, []query.ClusterMemberWhereClause{sc}, argIdx)
					if sub != "" {
						orParts = append(orParts, sub)
					}
					args = append(args, subArgs...)
				}
				if len(orParts) > 0 {
					parts = append(parts, "("+strings.Join(orParts, " OR ")+")")
				}
			}
		case "__NOT__":
			if sc, ok := w.Value.(query.ClusterMemberWhereClause); ok {
				sub, subArgs := buildClusterMemberWhere(c, []query.ClusterMemberWhereClause{sc}, argIdx)
				if sub != "" {
					parts = append(parts, "NOT ("+sub+")")
				}
				args = append(args, subArgs...)
			}
		default:
			field, err := quoteClusterMemberField(c, w.Field)
			if err != nil {
				parts = append(parts, "1 = 0")
				continue
			}
			switch w.Operator {
			case "IS NULL":
				parts = append(parts, field+" IS NULL")
			case "IN", "NOT IN":
				if vals, ok := w.Value.([]any); ok {
					if len(vals) == 0 {
						if w.Operator == "IN" {
							parts = append(parts, "1 = 0")
						} else {
							parts = append(parts, "1 = 1")
						}
					} else {
						phs := make([]string, len(vals))
						for i, v := range vals {
							*argIdx++
							phs[i] = c.placeholder(*argIdx)
							args = append(args, v)
						}
						parts = append(parts, field+" "+w.Operator+" ("+strings.Join(phs, ", ")+")")
					}
				}
			case "CONTAINS":
				*argIdx++
				parts = append(parts, field+" LIKE "+c.placeholder(*argIdx)+" ESCAPE '\\'")
				args = append(args, "%"+escapeLikePattern(fmt.Sprint(w.Value))+"%")
			case "STARTS_WITH":
				*argIdx++
				parts = append(parts, field+" LIKE "+c.placeholder(*argIdx)+" ESCAPE '\\'")
				args = append(args, escapeLikePattern(fmt.Sprint(w.Value))+"%")
			case "ENDS_WITH":
				*argIdx++
				parts = append(parts, field+" LIKE "+c.placeholder(*argIdx)+" ESCAPE '\\'")
				args = append(args, "%"+escapeLikePattern(fmt.Sprint(w.Value)))
			default:
				*argIdx++
				parts = append(parts, field+" "+w.Operator+" "+c.placeholder(*argIdx))
				args = append(args, w.Value)
			}
		}
	}
	return strings.Join(parts, " AND "), args
}

