func quotedDNSLineTable(c *Client) string { return c.quoteIdentifier("dns_lines") }
func quotedDNSLineColumns(c *Client) string {
	cols := []string{"id", "cluster_id", "name", "provider_code", "provider_parent_code", "sort_order", "created_at", "updated_at"}
	for i := range cols {
		cols[i] = c.quoteIdentifier(cols[i])
	}
	return strings.Join(cols, ", ")
}

func quoteDNSLineField(c *Client, field string) (string, error) {
	switch field {
	case "id":
		return c.quoteIdentifier(field), nil
	case "cluster_id":
		return c.quoteIdentifier(field), nil
	case "name":
		return c.quoteIdentifier(field), nil
	case "provider_code":
		return c.quoteIdentifier(field), nil
	case "provider_parent_code":
		return c.quoteIdentifier(field), nil
	case "sort_order":
		return c.quoteIdentifier(field), nil
	case "created_at":
		return c.quoteIdentifier(field), nil
	case "updated_at":
		return c.quoteIdentifier(field), nil
	default:
		return "", fmt.Errorf("unknown DNSLine field %q", field)
	}
}

// buildDNSLineWhere recursively builds a WHERE clause string and arguments.
func buildDNSLineWhere(c *Client, wheres []query.DNSLineWhereClause, argIdx *int) (string, []any) {
	var parts []string
	var args []any
	for _, w := range wheres {
		switch w.Field {
		case "__AND__":
			if subs, ok := w.Value.([]query.DNSLineWhereClause); ok {
				sub, subArgs := buildDNSLineWhere(c, subs, argIdx)
				if sub != "" {
					parts = append(parts, "("+sub+")")
				}
				args = append(args, subArgs...)
			}
		case "__OR__":
			if subs, ok := w.Value.([]query.DNSLineWhereClause); ok {
				var orParts []string
				for _, sc := range subs {
					sub, subArgs := buildDNSLineWhere(c, []query.DNSLineWhereClause{sc}, argIdx)
					if sub != "" {
						orParts = append(orParts, sub)
					}
					args = append(args, subArgs...)
				}
				if len(orParts) > 0 {
					parts = append(parts, "("+strings.Join(orParts, " OR ")+")")
				}
			}
		case "__NOT__":
			if sc, ok := w.Value.(query.DNSLineWhereClause); ok {
				sub, subArgs := buildDNSLineWhere(c, []query.DNSLineWhereClause{sc}, argIdx)
				if sub != "" {
					parts = append(parts, "NOT ("+sub+")")
				}
				args = append(args, subArgs...)
			}
		default:
			field, err := quoteDNSLineField(c, w.Field)
			if err != nil {
				parts = append(parts, "1 = 0")
				continue
			}
			switch w.Operator {
			case "IS NULL":
				parts = append(parts, field+" IS NULL")
			case "IN", "NOT IN":
				if vals, ok := w.Value.([]any); ok {
					if len(vals) == 0 {
						if w.Operator == "IN" {
							parts = append(parts, "1 = 0")
						} else {
							parts = append(parts, "1 = 1")
						}
					} else {
						phs := make([]string, len(vals))
						for i, v := range vals {
							*argIdx++
							phs[i] = c.placeholder(*argIdx)
							args = append(args, v)
						}
						parts = append(parts, field+" "+w.Operator+" ("+strings.Join(phs, ", ")+")")
					}
				}
			case "CONTAINS":
				*argIdx++
				parts = append(parts, field+" LIKE "+c.placeholder(*argIdx)+" ESCAPE '\\'")
				args = append(args, "%"+escapeLikePattern(fmt.Sprint(w.Value))+"%")
			case "STARTS_WITH":
				*argIdx++
				parts = append(parts, field+" LIKE "+c.placeholder(*argIdx)+" ESCAPE '\\'")
				args = append(args, escapeLikePattern(fmt.Sprint(w.Value))+"%")
			case "ENDS_WITH":
				*argIdx++
				parts = append(parts, field+" LIKE "+c.placeholder(*argIdx)+" ESCAPE '\\'")
				args = append(args, "%"+escapeLikePattern(fmt.Sprint(w.Value)))
			default:
				*argIdx++
				parts = append(parts, field+" "+w.Operator+" "+c.placeholder(*argIdx))
				args = append(args, w.Value)
			}
		}
	}
	return strings.Join(parts, " AND "), args
}

